DROP TABLE IF EXISTS `t_ticket_log`;
CREATE TABLE `t_ticket_log` (
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键, 自增',
  `prefix` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '前缀',
  `cargo_no` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '票据号 ',
  `international` tinyint NOT NULL COMMENT '国内国际, 1: 国内, 2: 国际',
  `ticket_type` tinyint NOT NULL COMMENT '票据类型, 1: 货单, 2: 邮单, 3: 变更单, 4: 纸质调拨单, 5: 纸箱提货单, 6: 公务免单',
  `type` tinyint NOT NULL COMMENT '操作类型, 1: 分配, 2: 入库, 3:核销, 4: 作废, 5: 已使用, 6: 回收, 7: 调配, 8: 配比, 9: 遗失,10:删除,11:未知,12:撤销核销,13:撤销作废',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '描述',
  `update_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人id',
  `create_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人名称',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `ticketId` (`cargo_no`,`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='单票操作日志表';

